<?php
require_once __DIR__.'/SpreadsheetRows.php';require_once __DIR__.'/../core/Database.php';
class UserImportService
{
    public const HEADERS=['employee_no','full_name','username','mobile','email','department','organizational_role','manager_employee_no','sales_line','status','password_optional'];
    public static function preview(string $path,string $fileName,string $mode,bool $allowEmpty,int $userId): int{$mode=in_array($mode,['create','update','upsert'],true)?$mode:'create';$ext=strtolower(pathinfo($fileName,PATHINFO_EXTENSION));$rows=SpreadsheetRows::associative(SpreadsheetRows::read($path,$ext));Database::execute('INSERT INTO user_import_batches(file_name,imported_by,mode,allow_empty_employee_no,total_rows,status,created_at) VALUES(?,?,?,?,?,"preview",NOW())',[$fileName,$userId,$mode,$allowEmpty?1:0,count($rows)]);$batch=(int)Database::lastInsertId();$numbers=array_filter(array_map(static fn($r)=>trim((string)($r['employee_no']??'')),$rows));$seen=[];$valid=0;$errors=0;foreach($rows as $row){$messages=[];$no=trim((string)($row['employee_no']??''));if($no===''&&!$allowEmpty)$messages[]='شماره پرسنلی خالی است.';if($no!==''&&isset($seen[$no]))$messages[]='شماره پرسنلی در فایل تکراری است.';$seen[$no]=true;if(trim((string)($row['full_name']??''))==='')$messages[]='نام و نام خانوادگی خالی است.';$email=trim((string)($row['email']??''));if($email===''||!filter_var($email,FILTER_VALIDATE_EMAIL))$messages[]='ایمیل معتبر نیست.';$existing=$no!==''?Database::fetch('SELECT id FROM users WHERE employee_no=?',[$no]):null;if($mode==='create'&&$existing)$messages[]='شماره پرسنلی قبلاً ثبت شده است.';if($mode==='update'&&!$existing)$messages[]='کاربر موجود برای بروزرسانی پیدا نشد.';$department=trim((string)($row['department']??''));if($department&&!Database::fetch('SELECT id FROM org_units WHERE title=? OR code=? LIMIT 1',[$department,$department]))$messages[]='واحد سازمانی پیدا نشد.';$role=trim((string)($row['organizational_role']??''));if($role&&!Database::fetch('SELECT id FROM org_roles WHERE title=? OR code=? LIMIT 1',[$role,$role]))$messages[]='نقش سازمانی پیدا نشد.';$manager=trim((string)($row['manager_employee_no']??''));if($manager&&!in_array($manager,$numbers,true)&&!Database::fetch('SELECT id FROM users WHERE employee_no=?',[$manager]))$messages[]='شماره پرسنلی مدیر مستقیم پیدا نشد.';$status=$messages?'error':'valid';$messages?$errors++:$valid++;Database::execute('INSERT INTO user_import_rows(batch_id,source_row,employee_no,raw_data_json,status,error_message,created_at) VALUES(?,?,?,?,?,?,NOW())',[$batch,(int)$row['_row'],$no?:null,json_encode($row,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$status,$messages?implode(' ',$messages):null]);}Database::execute('UPDATE user_import_batches SET success_count=?,error_count=? WHERE id=?',[$valid,$errors,$batch]);return $batch;}
    private static function uniqueUsername(string $base,?int $ignoreId=null): string{$base=preg_replace('/[^a-zA-Z0-9_.-]/','',strtolower($base))?:'user';$candidate=$base;$i=1;while(Database::fetch('SELECT id FROM users WHERE username=? AND id<>? LIMIT 1',[$candidate,$ignoreId?:0]))$candidate=$base.'.'.(++$i);return $candidate;}
    public static function commit(int $batchId,int $actor): array{$pdo=Database::connection();$pdo->beginTransaction();try{$batch=Database::fetch('SELECT * FROM user_import_batches WHERE id=? FOR UPDATE',[$batchId]);if(!$batch||$batch['status']!=='preview')throw new InvalidArgumentException('Batch قابل ثبت نیست.');$rows=Database::fetchAll('SELECT * FROM user_import_rows WHERE batch_id=? ORDER BY source_row',[$batchId]);$created=0;$updated=0;$skipped=0;$managerLinks=[];foreach($rows as $row){if($row['status']==='error'){$skipped++;continue;}$data=json_decode($row['raw_data_json'],true)?:[];$no=trim((string)($data['employee_no']??''));$existing=$no!==''?Database::fetch('SELECT * FROM users WHERE employee_no=?',[$no]):null;if($batch['mode']==='create'&&$existing){Database::execute("UPDATE user_import_rows SET status='skipped',error_message='کاربر از قبل وجود دارد.' WHERE id=?",[$row['id']]);$skipped++;continue;}if($batch['mode']==='update'&&!$existing){Database::execute("UPDATE user_import_rows SET status='skipped',error_message='کاربر برای بروزرسانی پیدا نشد.' WHERE id=?",[$row['id']]);$skipped++;continue;}$unit=trim((string)($data['department']??''));$unitRow=$unit!==''?Database::fetch('SELECT id,title FROM org_units WHERE title=? OR code=? LIMIT 1',[$unit,$unit]):null;$role=trim((string)($data['organizational_role']??''));$roleRow=$role!==''?Database::fetch('SELECT id,title,code FROM org_roles WHERE title=? OR code=? LIMIT 1',[$role,$role]):null;$username=trim((string)($data['username']??''));if($username==='')$username=$no?:trim((string)($data['mobile']??''));$username=self::uniqueUsername($username?:'user',$existing?(int)$existing['id']:null);$status=in_array(strtolower((string)($data['status']??'')),['disabled','inactive','0'],true)?'disabled':'active';$password=trim((string)($data['password_optional']??''));if($existing){$params=[trim((string)$data['full_name']),$username,trim((string)$data['mobile']),trim((string)$data['email']),$unitRow['title']??null,$roleRow['code']??null,$unitRow['id']??null,$roleRow['id']??null,trim((string)($data['sales_line']??'')),$status,$no?:null];$sql='UPDATE users SET name=?,username=?,mobile=?,email=?,department=?,role_key=?,org_unit_id=?,org_role_id=?,sales_line=?,status=?,employee_no=?,updated_at=NOW()';if($password!==''){$sql.=',password_hash=?,force_password_change=0';$params[]=password_hash($password,PASSWORD_DEFAULT);}$sql.=' WHERE id=?';$params[]=(int)$existing['id'];Database::execute($sql,$params);$userId=(int)$existing['id'];$updated++;$newStatus='updated';}else{$password=$password!==''?$password:bin2hex(random_bytes(8));Database::execute('INSERT INTO users(name,email,username,password_hash,role,status,department,role_key,sales_line,org_unit_id,org_role_id,employee_no,mobile,force_password_change,created_at,updated_at) VALUES(?,?,?,? ,"employee",?,?,?,?,?,?,?,?,?,NOW(),NOW())',[trim((string)$data['full_name']),trim((string)$data['email']),$username,password_hash($password,PASSWORD_DEFAULT),$status,$unitRow['title']??null,$roleRow['code']??null,trim((string)($data['sales_line']??'')),$unitRow['id']??null,$roleRow['id']??null,$no?:null,trim((string)($data['mobile']??'')),trim((string)($data['password_optional']??''))===''?1:0]);$userId=(int)Database::lastInsertId();$created++;$newStatus='created';}if(!empty($data['manager_employee_no']))$managerLinks[]=['user_id'=>$userId,'manager_no'=>trim((string)$data['manager_employee_no'])];Database::execute('UPDATE user_import_rows SET status=?,error_message=NULL WHERE id=?',[$newStatus,$row['id']]);}foreach($managerLinks as $link){$manager=Database::fetch('SELECT id FROM users WHERE employee_no=?',[$link['manager_no']]);if($manager){Database::execute('UPDATE users SET parent_user_id=? WHERE id=?',[(int)$manager['id'],$link['user_id']]);Database::execute('INSERT IGNORE INTO manager_employees(manager_id,employee_id,assigned_by,created_at) VALUES(?,?,?,NOW())',[(int)$manager['id'],$link['user_id'],$actor]);}}Database::execute("UPDATE user_import_batches SET status='committed',success_count=?,error_count=?,committed_at=NOW() WHERE id=?",[$created+$updated,$skipped,$batchId]);$pdo->commit();return compact('created','updated','skipped');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
}
